const MapUnitedStates = ({ element, active, highlighted, width, onClick, onChange }) => {
  return (
    <ElementWrapper
      element={element}
      onClick={onClick}
      onChange={onChange}
      maxWidth={width}
      active={active}
      highlighted={highlighted}
      resizeHandles={['e']}
      editable
      fit
    >
      <MapUnitedStatesContent element={element} />
    </ElementWrapper>
  );
};

export const MapUnitedStatesPresent = ({ element }) => {
  return <MapUnitedStatesContent element={element} />;
};

export const MapUnitedStatesPreview = () => {
  return <MapUnitedStatesContent element={{ config: { data: [], fill: '#f9fafb', stroke: '#f9fafb' } }} />;
};

